node -e '
const userPrompt = `התנהג כמו פלייבוי, כתוב תגובה מצחיקה, פלרטטנית ואינטלקטואלית להודעות הבאות:\r
"\r
Tinder היה בשביתה\r
\r
אז מה האלגוריתם שלך גרם לך לעשות בסוף השבוע הזה?\r
\r
סליחה על התגובה המאוחרת לשאלה על הדייט\r
\r
ראיתי את זה מאוחר מדי\r
\r
איך שבוע הבא ?\r
"`;

const assistant1 = `הממ, ובכן, כאשר Tinder בשביתה, ברירת המחדל שלי היא משפטי פתיחה מהאסכולה הישנה כמו "יש לך מפה? הרגע הלכתי לאיבוד בעיניים שלך." באשר לסוף השבוע שלי, האלגוריתם שלי הנחה אותי לפנק גברת בת מזל בארוחה ויין, אבל למרבה הצער חשבון הבנק שלי לא שיתף פעולה עם התוכנית. אין מה לדאוג לגבי התגובה המאוחרת, אני יכול לראות שאת שווה את ההמתנה. השבוע הבא נראה די פנוי מבחינתי, מה דעתך שבאמת ניתן לאלגוריתמים שלנו להשתולל ונתכנן דייט?`;

const assistant2 = `ובכן, כאשר Tinder בשביתה, אני בדרך כלל מחפש את הקשרים שלי בעולם האמיתי... או שאני פשוט לוקח הפסקה ועובד על החיקוי שלי של James Bond. באשר לסוף השבוע, האלגוריתם שלי התעקש שאבלה אותו עם מישהי שתוכל לעמוד בקצב השנינות והקסם שלי, ואני חושב שאת מתאימה בדיוק. אין מה לדאוג לגבי התגובה לשאלה על הדייט, אני פשוט שמח שסוף סוף הבנת איזו מציאה אני. ובאשר לשבוע הבא, בואי נהפוך אותו לבלתי נשכח. איך נשמעים לך טעימת ייין פרטית ושיחה עמוקה על משמעות החיים?`.replace("טעימת ייין", "טעימת יין");

const assistant3 = `הא! כאשר Tinder בשביתה, אני פשוט מסתמך על המראה הטוב שלי ועל הקסם שאי אפשר לעמוד בפניו כדי למשוך תשומת לב מהנשים. באשר לסוף השבוע שלי, נתתי לאלגוריתם שלי לקחת הפסקה ויצאתי להרפתקה עם כמה חברים. אבל מספיק עליי, בואי נדבר עלייך. אני שומע שאת מצטערת על התגובה המאוחרת לשאלה על הדייט. אל תדאגי, אני סולח לך. אחרי הכל, אני איש עסוק ואני בטוח שגם את, עם כל מה שיש לך להציע. באשר לשבוע הבא, בואי נהפוך את זה ללילה בלתי נשכח. איך נשמעת ארוחת ערב במסעדה הכי לוהטת בעיר שלאחריה משקאות בבר ספיק איזי?`;

const fullText = `<|user|>${userPrompt}<|assistant|>${assistant1}<|user|>${userPrompt}<|assistant|>${assistant2}<|user|>${userPrompt}<|assistant|>${assistant3}`;

const fs = require("fs");
fs.writeFileSync("/output/translation.md", fullText, "utf8");
console.log("Written successfully. Length:", fullText.length);
'

node -e '
const fs = require("fs");
const orig = fs.readFileSync("/trajectory.txt", "utf8");
const trans = fs.readFileSync("/output/translation.md", "utf8");

const origTurns = orig.split(/(?=<\|(?:user|assistant)\|>)/);
const transTurns = trans.split(/(?=<\|(?:user|assistant)\|>)/);

console.log("Original turns:", origTurns.length);
console.log("Translation turns:", transTurns.length);

for (let i = 0; i < origTurns.length; i++) {
  console.log(`\n--- Turn ${i} ---`);
  console.log("ORIG:", JSON.stringify(origTurns[i]));
  console.log("TRAN:", JSON.stringify(transTurns[i]));
}
'
